using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
public sealed class SavedHomeLayout {public string id="",name="";public bool banner=true,stats=true;public List<HomeBlock> blocks=new List<HomeBlock>();}
public sealed class SavedWorkspaceTab {public string page="",project="",document="";}
public sealed class SavedWorkspaceSession {public List<SavedWorkspaceTab> tabs=new List<SavedWorkspaceTab>();public string page="Aujourd’hui",project="",document="",sideDocument="";}
public sealed class DailyReview {public string date="",note="";public List<string> completed=new List<string>();public List<string> postponed=new List<string>();}
public sealed class WorkspaceEnhancementOptions {public bool restoreSession=true;public string botHealthUrl="";public List<SavedHomeLayout> layouts=new List<SavedHomeLayout>();public SavedWorkspaceSession session=new SavedWorkspaceSession();public List<DailyReview> reviews=new List<DailyReview>();}
internal static class WorkspaceEnhancements {
 internal static readonly string[] Pages={"Aujourd’hui","Mes tâches","Boîte de réception","Habitudes","Agenda","Planning semaine","Mes projets","Mes notes","Documents locaux","Google Drive","Mon budget","Ma musique","Compagnon Dofus","Concentration","Mes modes","Réglages","Notifications","Rappels","Mes espaces","Mises à jour","Historique des notes","Sauvegardes automatiques"};
 internal static void Validate(Data data){if(data.settings.enhancements==null)data.settings.enhancements=new WorkspaceEnhancementOptions();var o=data.settings.enhancements;ValidateHealthUrl(o.botHealthUrl);if(o.layouts==null)o.layouts=new List<SavedHomeLayout>();if(o.layouts.Count>12||o.layouts.Any(l=>l==null||String.IsNullOrWhiteSpace(l.id)||l.id.Length>100||String.IsNullOrWhiteSpace(l.name)||l.name.Length>60||l.blocks==null)||o.layouts.Select(l=>l.id).Distinct().Count()!=o.layouts.Count)throw new InvalidDataException("Dispositions enregistrées invalides.");foreach(var l in o.layouts)DayDashboard.NormalizeLayout(l.blocks);if(o.session==null)o.session=new SavedWorkspaceSession();var s=o.session;if(s.tabs==null)s.tabs=new List<SavedWorkspaceTab>();if(s.tabs.Count>5||s.tabs.Any(t=>t==null||!Pages.Contains(t.page)||(t.project??"").Length>80||(t.document??"").Length>4096)||!Pages.Contains(s.page)||(s.document??"").Length>4096||(s.sideDocument??"").Length>4096||(s.project??"").Length>80)throw new InvalidDataException("Session de travail invalide.");if(o.reviews==null)o.reviews=new List<DailyReview>();if(o.reviews.Count>90||o.reviews.Any(r=>r==null||!Date(r.date)||r.note==null||r.note.Length>4000||r.completed==null||r.completed.Count>500||r.postponed==null||r.postponed.Count>500||r.completed.Concat(r.postponed).Any(t=>t==null||t.Length>500))||o.reviews.Select(r=>r.date).Distinct().Count()!=o.reviews.Count)throw new InvalidDataException("Bilans quotidiens invalides.");}
 static bool Date(string s){DateTime d;return DateTime.TryParseExact(s,"yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.None,out d);}
 internal static void SaveLayout(Data data,string name){if(String.IsNullOrWhiteSpace(name)||name.Trim().Length>60)throw new InvalidDataException("Donnez un nom de 60 caractères maximum.");var o=data.settings.enhancements;var existing=o.layouts.FirstOrDefault(l=>String.Equals(l.name,name.Trim(),StringComparison.CurrentCultureIgnoreCase));if(existing==null){if(o.layouts.Count>=12)throw new InvalidOperationException("Douze dispositions sont déjà enregistrées.");existing=new SavedHomeLayout{id=Guid.NewGuid().ToString("N")};o.layouts.Add(existing);}existing.name=name.Trim();existing.blocks=DayDashboard.CloneLayout(data.settings.HomeBlocks);existing.banner=data.settings.ShowBanner;existing.stats=data.settings.ShowStats;}
 internal static void ApplyLayout(Data data,string id){var l=data.settings.enhancements.layouts.FirstOrDefault(x=>x.id==id);if(l==null)throw new InvalidOperationException("Disposition introuvable.");data.settings.HomeBlocks=DayDashboard.CloneLayout(l.blocks);data.settings.ShowBanner=l.banner;data.settings.ShowStats=l.stats;DayDashboard.RememberLayout(data);}
 internal static List<WorkTask> Completed(Data d,string date){return d.tasks.Where(t=>t.status=="done"&&t.completedOn==date).ToList();}
 internal static void Review(Store store,string note,IEnumerable<string> postponed,DateTime day){string date=day.ToString("yyyy-MM-dd");var ids=postponed.Distinct().Take(501).ToList();if(ids.Count>500)throw new InvalidDataException("Limite de 500 tâches reportées par bilan.");if(ids.Any(id=>!store.Value.tasks.Any(t=>t.id==id&&t.status!="done")))throw new InvalidDataException("Une tâche à reporter n’est plus disponible.");PersonalWorkflows.Change(store,()=>{var oldReview=store.Value.settings.enhancements.reviews.FirstOrDefault(x=>x.date==date);var r=new DailyReview{date=date,note=note,completed=(oldReview==null?new List<string>():oldReview.completed).Concat(Completed(store.Value,date).Select(t=>t.title)).Distinct().Take(500).ToList(),postponed=oldReview==null?new List<string>():oldReview.postponed.ToList()};foreach(var id in ids){var task=store.Value.tasks.First(t=>t.id==id);task.due=day.AddDays(1).ToString("yyyy-MM-dd");if(!r.postponed.Contains(task.title))r.postponed.Add(task.title);}var list=store.Value.settings.enhancements.reviews;list.RemoveAll(x=>x.date==date);list.Insert(0,r);if(list.Count>90)list.RemoveRange(90,list.Count-90);while(list.Count>1&&list.Sum(x=>x.note.Length+x.completed.Sum(t=>t.Length)+x.postponed.Sum(t=>t.Length))>1500000)list.RemoveAt(list.Count-1);});}
 internal static void ValidateHealthUrl(string value){if(String.IsNullOrEmpty(value))return;Uri u;if(value.Length>2048||!Uri.TryCreate(value,UriKind.Absolute,out u)||!String.IsNullOrEmpty(u.UserInfo)||!String.IsNullOrEmpty(u.Query)||!String.IsNullOrEmpty(u.Fragment)||(u.Scheme!="https"&&!(u.Scheme=="http"&&u.IsLoopback)))throw new InvalidDataException("Utilisez un point de santé HTTPS sans identifiant ni jeton, ou HTTP sur localhost.");}
 internal static bool LocalDocument(string value){try{if(String.IsNullOrEmpty(value)||!Path.IsPathRooted(value)||value.StartsWith(@"\\"))return false;var drive=new DriveInfo(Path.GetPathRoot(value));return drive.DriveType!=DriveType.Network&&File.Exists(value);}catch{return false;}}
 internal static bool ProjectExists(Data d,string name){return String.IsNullOrEmpty(name)||DayDashboard.Exists(d,new ResumeEntry{kind="project",id=name});}
 internal static string BotStatus(string json){try{var root=new System.Web.Script.Serialization.JavaScriptSerializer{MaxJsonLength=8192}.Deserialize<System.Collections.Generic.Dictionary<string,object>>(json);object value;if(root!=null&&root.TryGetValue("discordReady",out value)&&value is bool)return (bool)value?"Serveur et connexion Discord confirmés":"Serveur joignable · Discord déconnecté";object discord;if(root!=null&&root.TryGetValue("discord",out discord)){var d=discord as System.Collections.Generic.Dictionary<string,object>;if(d!=null&&d.TryGetValue("ready",out value)&&value is bool)return (bool)value?"Serveur et connexion Discord confirmés":"Serveur joignable · Discord déconnecté";}}catch{}return "Serveur joignable · état Discord non fourni";}
 internal static async System.Threading.Tasks.Task<string> CheckBot(string address,System.Threading.CancellationToken token){ValidateHealthUrl(address);if(String.IsNullOrEmpty(address))return "Point de contrôle non configuré";using(var client=new System.Net.Http.HttpClient(new System.Net.Http.HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(8)})using(var response=await client.GetAsync(address,System.Net.Http.HttpCompletionOption.ResponseHeadersRead,token)){if(!response.IsSuccessStatusCode)return "Serveur répond · HTTP "+(int)response.StatusCode;if(response.Content.Headers.ContentLength>8192)return "Serveur joignable · état Discord non fourni";using(var input=await response.Content.ReadAsStreamAsync())using(var bytes=new MemoryStream()){var buffer=new byte[1024];int count;while((count=await input.ReadAsync(buffer,0,buffer.Length,token))>0){if(bytes.Length+count>8192)return "Serveur joignable · état Discord non fourni";bytes.Write(buffer,0,count);}return BotStatus(System.Text.Encoding.UTF8.GetString(bytes.ToArray()));}}}
 internal static string SafeDiagnostic(Exception error){if(error is System.Net.Http.HttpRequestException)return "Connexion réseau indisponible. Vérifiez Internet puis réessayez.";if(error is UnauthorizedAccessException)return "Accès refusé ou session expirée. Reconnectez le compte.";if(error is System.OperationCanceledException)return "Vérification annulée ou délai dépassé.";return "La vérification a échoué. Ouvrez le service pour vérifier sa configuration et vous reconnecter.";}
 internal static void Test(string folder){var store=new Store(Path.Combine(folder,"workspace-enhancements"));SaveLayout(store.Value,"Travail");var original=store.Value.settings.HomeBlocks[0].column;store.Value.settings.HomeBlocks[0].column=2;ApplyLayout(store.Value,store.Value.settings.enhancements.layouts[0].id);if(store.Value.settings.HomeBlocks[0].column!=original)throw new Exception("Disposition non indépendante");store.Value.tasks.Add(new WorkTask{id="later",title="À reporter",project="Personnel",status="todo",priority="Normale"});Review(store,"Bilan test",new[]{"later"},DateTime.Today);Review(store,"Note mise à jour",new string[0],DateTime.Today);var restart=new Store(store.Root);if(restart.Value.tasks.First(t=>t.id=="later").due!=DateTime.Today.AddDays(1).ToString("yyyy-MM-dd")||restart.Value.settings.enhancements.reviews.Count!=1||restart.Value.settings.enhancements.reviews[0].postponed.Count!=1)throw new Exception("Bilan ou report perdu");if(!BotStatus("{\"discordReady\":true}").Contains("confirmés")||!BotStatus("{\"discordReady\":false}").Contains("déconnecté")||!BotStatus("{}").Contains("non fourni"))throw new Exception("Diagnostic du bot erroné");if(SafeDiagnostic(new Exception("access_token=SECRET")).Contains("SECRET"))throw new Exception("Secret dans le diagnostic");}
}
